// Проверка и очистка заявки. Те же правила, что в api/app/leads.py.
const cfg = $('Настройки').first().json;
const raw = $json.body || {};
const clean = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
// Свои формы шлют JSON (name, phone…). Tilda шлёт поля формы как Name / Phone / Comments,
// а при подключении вебхука — проверочный запрос test=test, на него нужно ответить 200.
const pick = (...keys) => keys.map((k) => raw[k]).find((v) => v !== undefined && v !== '');
const b = {
  name: pick('name', 'Name'), phone: pick('phone', 'Phone'),
  message: pick('message', 'Comments', 'comments', 'comment', 'Textarea'),
  source: pick('source') || (raw.formname ? 'tilda: ' + raw.formname : raw.tranid ? 'tilda' : ''),
  lang: raw.lang, product: raw.product, qty: raw.qty, website: raw.website,
};

const name = clean(b.name).slice(0, 100);
const digits = clean(b.phone).replace(/\D/g, '');
let error = '';
if (raw.test === 'test') error = 'ping';
else if (clean(b.website)) error = 'honeypot';      // скрытое поле заполняют только боты
else if (name.length < 2) error = 'name';
else if (digits.length < 9 || digits.length > 15) error = 'phone';

let phone = '+' + digits;                             // 8 921… / 921… → +7 921…
if (digits.length === 11 && (digits[0] === '7' || digits[0] === '8')) phone = '+7' + digits.slice(1);
else if (digits.length === 10 && digits[0] === '9') phone = '+7' + digits;

const local = new Date().toLocaleString('sv-SE', { timeZone: cfg.timezone }).slice(0, 16);
const id = 'L-' + local.slice(0, 10).replace(/-/g, '') + '-' + local.slice(11, 16).replace(':', '') +
  '-' + Math.random().toString(16).slice(2, 6);
const lang = ['ru', 'ar', 'en'].includes(b.lang) ? b.lang : 'ru';
const message = clean(b.message).slice(0, 4000);
const source = clean(b.source) || 'сайт';
const product = b.product ? String(b.product) : null;

const lead = { id, received_at: local, name, phone, message, source, lang, product, qty: b.qty ?? null };
const llm_user = `Имя: ${name}\nТелефон: ${phone}\nИсточник: ${source}\nЯзык страницы: ${lang}\n` +
  `Товар: ${product || '-'}\nСообщение: ${message}`;

return { json: { valid: !error, error, lead, llm_user } };

// Категория и сводка: берём ответ нейросети, а если её нет или ответ битый — правила по ключевым словам.
// R подставляется из prompts/triage_rules.json скриптом scripts/build_workflow.py (тот же файл читает Python-версия).
const R = {"rules": [["spam", "https?://|казино|crypto|крипт|раскрут|seo[- ]?продвиж|заработ[а-яё]* от|viagra|ставки на спорт"], ["complaint", "жалоб|не приш|не дошл|разбит|испорч|верн[а-яё]* деньг|возврат|ужас|обман|شكو|مكسور|لم يصل|استرجاع|complain|broken|refund"], ["wholesale", "(?<![а-яё])опт(?:а|ом|ов[а-яё]*)?(?![а-яё])|партн[её]р|для магазин|кофе[ей]н|ресторан|дистриб|поставк|جملة|موزع|فندق|فنادق|متجر|مقهى|wholesale|distribut|horeca"], ["order", "заказ|купить|хочу|доставк|набор|اطلب|أطلب|طلب|اشتري|أريد|order|buy"]], "order_products": ["taiga", "linden", "buckwheat", "gift"], "labels_ru": {"order": "Заказ", "wholesale": "Опт / партнёрство", "question": "Вопрос", "complaint": "Жалоба", "spam": "Спам"}, "urgency_ru": {"high": "Срочно", "normal": "Обычно", "low": "Не срочно"}, "default_urgency": {"order": "high", "complaint": "high", "wholesale": "normal", "question": "normal", "spam": "low"}, "icons": {"order": "🟢", "wholesale": "🔵", "question": "⚪️", "complaint": "🔴", "spam": "🚫"}, "reply_templates": {"ru": "Здравствуйте, {name}! Спасибо за заявку — менеджер свяжется с вами в ближайшее время.", "ar": "مرحبًا {name}، شكرًا لتواصلك معنا! سيتواصل معك أحد ممثلينا قريبًا.", "en": "Hi {name}, thanks for reaching out! Our manager will contact you shortly."}};
const lead = $('Проверка и очистка').item.json.lead;

function byRules() {
  const text = (lead.message || '').toLowerCase();
  let category = 'question';
  for (const [cat, pattern] of R.rules) {
    if (new RegExp(pattern, 'u').test(text)) { category = cat; break; }
  }
  if (category === 'question' && lead.product === 'wholesale') category = 'wholesale';
  else if (category === 'question' && R.order_products.includes(lead.product)) category = 'order';
  const label = R.labels_ru[category];
  const tpl = R.reply_templates[lead.lang] || R.reply_templates.ru;
  return {
    category, urgency: R.default_urgency[category],
    summary: lead.message ? `${label}: ${lead.message.slice(0, 120)}` : label,
    reply_draft: tpl.replace('{name}', lead.name), by: 'rules',
  };
}

function fromAI() {
  const content = $json.choices?.[0]?.message?.content;
  const match = content && content.match(/\{[\s\S]*\}/);   // модель иногда оборачивает JSON в ```
  if (!match) return null;
  let d;
  try { d = JSON.parse(match[0]); } catch (e) { return null; }
  const fb = byRules();
  const category = R.labels_ru[d.category] ? d.category : fb.category;
  const urgency = R.urgency_ru[d.urgency] ? d.urgency : R.default_urgency[category];
  return {
    category, urgency, by: 'ai',
    summary: String(d.summary || fb.summary).trim(),
    reply_draft: String(d.reply_draft || fb.reply_draft).trim(),
  };
}

const t = fromAI() || byRules();
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = [
  `${R.icons[t.category]} <b>${R.labels_ru[t.category]}</b>` + (t.urgency === 'high' ? ' · <b>срочно</b>' : ''),
  `👤 ${esc(lead.name)} · <code>${esc(lead.phone)}</code>`,
  `📝 ${esc(t.summary)}`,
];
if (lead.message) lines.push(`💬 <i>${esc(lead.message.slice(0, 600))}</i>`);
lines.push(`✍️ Черновик ответа: ${esc(t.reply_draft)}`);
lines.push(`🌐 ${esc(lead.source)} · ${lead.lang} · ${lead.id}`);

return { json: {
  'Дата': lead.received_at, 'ID': lead.id, 'Имя': lead.name, 'Телефон': lead.phone,
  'Категория': R.labels_ru[t.category], 'Срочность': R.urgency_ru[t.urgency], 'Сводка': t.summary,
  'Сообщение': lead.message, 'Источник': lead.source, 'Язык': lead.lang,
  'Черновик ответа': t.reply_draft, 'Разбор': t.by === 'ai' ? 'AI' : 'правила',
  category: t.category, telegram_text: lines.join('\n'),
} };
